CREATE TABLE IF NOT EXISTS "customers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity. 320 chars is the RFC 5321 maximum for an address.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name shown to the restaurant and the courier at handover.
	"full_name" VARCHAR(160) NOT NULL,
	-- E.164 number. Not optional here: couriers call it, and delivery fails without it.
	"phone" VARCHAR(32) NOT NULL,
	-- Preselected tip in basis points of subtotal. Stored per customer so the checkout default follows them across devices.
	"default_tip_bps" INTEGER NOT NULL DEFAULT 1500,
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last profile change.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "customers" IS 'A person who orders food. Addresses are not kept in a book here; each order snapshots the address it was delivered to, because a corrected home address must not rewrite where last month parcel went.';
COMMENT ON COLUMN "customers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "customers"."email" IS 'Login identity. 320 chars is the RFC 5321 maximum for an address.';
COMMENT ON COLUMN "customers"."full_name" IS 'Name shown to the restaurant and the courier at handover.';
COMMENT ON COLUMN "customers"."phone" IS 'E.164 number. Not optional here: couriers call it, and delivery fails without it.';
COMMENT ON COLUMN "customers"."default_tip_bps" IS 'Preselected tip in basis points of subtotal. Stored per customer so the checkout default follows them across devices.';
COMMENT ON COLUMN "customers"."created_at" IS 'Signup time.';
COMMENT ON COLUMN "customers"."updated_at" IS 'Last profile change.';

CREATE TABLE IF NOT EXISTS "restaurants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Storefront name as shown in search results.
	"name" VARCHAR(200) NOT NULL,
	-- URL segment for the store page.
	"slug" VARCHAR(220) NOT NULL UNIQUE,
	-- Pickup address the courier navigates to.
	"address_line" VARCHAR(300) NOT NULL,
	-- City, used to scope search and regional fee rules.
	"city" VARCHAR(120) NOT NULL,
	-- ISO 3166-1 alpha-2 code. Drives tax and currency defaults.
	"country_code" CHAR(2) NOT NULL,
	-- Pickup latitude. Six decimals is roughly 11 cm, far more than dispatch needs.
	"latitude" DECIMAL(9,6) NOT NULL,
	-- Pickup longitude, same precision as latitude.
	"longitude" DECIMAL(9,6) NOT NULL,
	-- IANA zone, e.g. America/New_York. Opening hours are local wall-clock times, not instants.
	"timezone" VARCHAR(64) NOT NULL,
	-- ISO 4217 currency every price on this menu is denominated in.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Platform commission in basis points, negotiated per restaurant. Copied onto each order fee row so a renegotiation does not restate old settlements.
	"commission_bps" INTEGER NOT NULL DEFAULT 1500,
	-- Rolling estimate of kitchen time. Dispatch subtracts it from the promise so the courier arrives as the bag is bagged, not twenty minutes early.
	"prep_time_minutes" INTEGER NOT NULL DEFAULT 15,
	-- Manual kill switch the restaurant tablet toggles when the kitchen is swamped.
	"is_accepting_orders" BOOLEAN NOT NULL DEFAULT true,
	-- Onboarding time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "restaurants" IS 'A merchant storefront. Geography lives here as plain lat/lng columns rather than a spatial type so the schema exports cleanly to every dialect; a production deployment would add a geography index.';
COMMENT ON COLUMN "restaurants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "restaurants"."name" IS 'Storefront name as shown in search results.';
COMMENT ON COLUMN "restaurants"."slug" IS 'URL segment for the store page.';
COMMENT ON COLUMN "restaurants"."address_line" IS 'Pickup address the courier navigates to.';
COMMENT ON COLUMN "restaurants"."city" IS 'City, used to scope search and regional fee rules.';
COMMENT ON COLUMN "restaurants"."country_code" IS 'ISO 3166-1 alpha-2 code. Drives tax and currency defaults.';
COMMENT ON COLUMN "restaurants"."latitude" IS 'Pickup latitude. Six decimals is roughly 11 cm, far more than dispatch needs.';
COMMENT ON COLUMN "restaurants"."longitude" IS 'Pickup longitude, same precision as latitude.';
COMMENT ON COLUMN "restaurants"."timezone" IS 'IANA zone, e.g. America/New_York. Opening hours are local wall-clock times, not instants.';
COMMENT ON COLUMN "restaurants"."currency_code" IS 'ISO 4217 currency every price on this menu is denominated in.';
COMMENT ON COLUMN "restaurants"."commission_bps" IS 'Platform commission in basis points, negotiated per restaurant. Copied onto each order fee row so a renegotiation does not restate old settlements.';
COMMENT ON COLUMN "restaurants"."prep_time_minutes" IS 'Rolling estimate of kitchen time. Dispatch subtracts it from the promise so the courier arrives as the bag is bagged, not twenty minutes early.';
COMMENT ON COLUMN "restaurants"."is_accepting_orders" IS 'Manual kill switch the restaurant tablet toggles when the kitchen is swamped.';
COMMENT ON COLUMN "restaurants"."created_at" IS 'Onboarding time.';

CREATE INDEX "idx_restaurants_city_open"
ON "restaurants" ("city", "is_accepting_orders");

CREATE TABLE IF NOT EXISTS "menu_sections" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning restaurant.
	"restaurant_id" BIGINT NOT NULL,
	-- Heading shown on the menu, e.g. Burritos or Sides.
	"name" VARCHAR(120) NOT NULL,
	-- Optional blurb under the heading.
	"description" VARCHAR(400),
	-- Manual sort order. Restaurants care intensely about what appears first.
	"position" INTEGER NOT NULL DEFAULT 0,
	-- Local start of the window this section is orderable. Null means all day.
	"available_from" TIME,
	-- Local end of the window. Null means all day. This pair is what makes a breakfast menu possible without a second restaurant row.
	"available_to" TIME,
	-- Hides a whole section without deleting its items.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "menu_sections" IS 'A heading on the menu. Time windows live here rather than on items because a restaurant thinks in terms of a breakfast menu, not a hundred individually scheduled dishes.';
COMMENT ON COLUMN "menu_sections"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "menu_sections"."restaurant_id" IS 'Owning restaurant.';
COMMENT ON COLUMN "menu_sections"."name" IS 'Heading shown on the menu, e.g. Burritos or Sides.';
COMMENT ON COLUMN "menu_sections"."description" IS 'Optional blurb under the heading.';
COMMENT ON COLUMN "menu_sections"."position" IS 'Manual sort order. Restaurants care intensely about what appears first.';
COMMENT ON COLUMN "menu_sections"."available_from" IS 'Local start of the window this section is orderable. Null means all day.';
COMMENT ON COLUMN "menu_sections"."available_to" IS 'Local end of the window. Null means all day. This pair is what makes a breakfast menu possible without a second restaurant row.';
COMMENT ON COLUMN "menu_sections"."is_active" IS 'Hides a whole section without deleting its items.';

CREATE INDEX "idx_menu_sections_restaurant_position"
ON "menu_sections" ("restaurant_id", "position");

CREATE TABLE IF NOT EXISTS "menu_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Section the item appears under. An item belongs to exactly one section; a dish sold in two places is two rows, because its price and photo usually differ.
	"section_id" BIGINT NOT NULL,
	-- Dish name as printed on the menu.
	"name" VARCHAR(200) NOT NULL,
	-- Ingredient blurb shown under the name.
	"description" VARCHAR(600),
	-- Price before any modifier deltas, in minor units. Integers only; never float money.
	"base_price_cents" INTEGER NOT NULL,
	-- ISO 4217 currency for base_price_cents.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Declared energy content. Null where the restaurant has not supplied it, which is most of them.
	"calories" INTEGER,
	-- Permanent availability. False for a dish taken off the menu.
	"is_available" BOOLEAN NOT NULL DEFAULT true,
	-- Temporary sell-out. Set to end of service when the kitchen runs out; a background sweep clears it rather than someone remembering to flip a flag back.
	"sold_out_until" TIMESTAMP,
	-- Sort order within the section.
	"position" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "menu_items" IS 'A dish. It carries only its base price: everything a customer can change about it is expressed through modifier groups, so the price is computed, not enumerated.';
COMMENT ON COLUMN "menu_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "menu_items"."section_id" IS 'Section the item appears under. An item belongs to exactly one section; a dish sold in two places is two rows, because its price and photo usually differ.';
COMMENT ON COLUMN "menu_items"."name" IS 'Dish name as printed on the menu.';
COMMENT ON COLUMN "menu_items"."description" IS 'Ingredient blurb shown under the name.';
COMMENT ON COLUMN "menu_items"."base_price_cents" IS 'Price before any modifier deltas, in minor units. Integers only; never float money.';
COMMENT ON COLUMN "menu_items"."currency_code" IS 'ISO 4217 currency for base_price_cents.';
COMMENT ON COLUMN "menu_items"."calories" IS 'Declared energy content. Null where the restaurant has not supplied it, which is most of them.';
COMMENT ON COLUMN "menu_items"."is_available" IS 'Permanent availability. False for a dish taken off the menu.';
COMMENT ON COLUMN "menu_items"."sold_out_until" IS 'Temporary sell-out. Set to end of service when the kitchen runs out; a background sweep clears it rather than someone remembering to flip a flag back.';
COMMENT ON COLUMN "menu_items"."position" IS 'Sort order within the section.';

CREATE INDEX "idx_menu_items_section_position"
ON "menu_items" ("section_id", "position");

CREATE TABLE IF NOT EXISTS "modifier_groups" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning restaurant. Groups are restaurant-scoped so one Choose your salsa definition can be attached to thirty items.
	"restaurant_id" BIGINT NOT NULL,
	-- Question put to the customer, e.g. Choose a protein.
	"name" VARCHAR(120) NOT NULL,
	-- Lower bound on selections. 1 or more makes the group required; 0 makes it optional. Requiredness is derived from this, never stored twice.
	"min_choices" INTEGER NOT NULL DEFAULT 0,
	-- Upper bound on selections. Null means unlimited. Equal to min_choices for a strict pick-one.
	"max_choices" INTEGER,
	-- Whether the same modifier can be chosen twice, as in double bacon. Changes the meaning of max_choices from distinct options to total picks.
	"allow_duplicates" BOOLEAN NOT NULL DEFAULT false,
	-- Default order among the groups of an item, overridable per item.
	"position" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "modifier_groups" IS 'The reusable question behind every customisation. min_choices and max_choices are the whole validation contract: the client renders radio buttons or checkboxes from them, and the server re-checks them at order time.';
COMMENT ON COLUMN "modifier_groups"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "modifier_groups"."restaurant_id" IS 'Owning restaurant. Groups are restaurant-scoped so one Choose your salsa definition can be attached to thirty items.';
COMMENT ON COLUMN "modifier_groups"."name" IS 'Question put to the customer, e.g. Choose a protein.';
COMMENT ON COLUMN "modifier_groups"."min_choices" IS 'Lower bound on selections. 1 or more makes the group required; 0 makes it optional. Requiredness is derived from this, never stored twice.';
COMMENT ON COLUMN "modifier_groups"."max_choices" IS 'Upper bound on selections. Null means unlimited. Equal to min_choices for a strict pick-one.';
COMMENT ON COLUMN "modifier_groups"."allow_duplicates" IS 'Whether the same modifier can be chosen twice, as in double bacon. Changes the meaning of max_choices from distinct options to total picks.';
COMMENT ON COLUMN "modifier_groups"."position" IS 'Default order among the groups of an item, overridable per item.';

CREATE TABLE IF NOT EXISTS "modifiers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Group this option belongs to.
	"modifier_group_id" BIGINT NOT NULL,
	-- Option label, e.g. Extra guacamole.
	"name" VARCHAR(120) NOT NULL,
	-- Signed adjustment to the line price. Negative for a discount such as no cheese, zero for a free choice.
	"price_delta_cents" INTEGER NOT NULL DEFAULT 0,
	-- Preselected when the picker opens. Defaults still produce order_item_modifiers rows, so a receipt shows what was actually on the dish.
	"is_default" BOOLEAN NOT NULL DEFAULT false,
	-- Lets the kitchen kill a single option without taking down the group.
	"is_available" BOOLEAN NOT NULL DEFAULT true,
	-- Sort order within the group.
	"position" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "modifiers" IS 'One selectable option. The price lives on the option rather than on the item so a single dish can be priced by what goes into it.';
COMMENT ON COLUMN "modifiers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "modifiers"."modifier_group_id" IS 'Group this option belongs to.';
COMMENT ON COLUMN "modifiers"."name" IS 'Option label, e.g. Extra guacamole.';
COMMENT ON COLUMN "modifiers"."price_delta_cents" IS 'Signed adjustment to the line price. Negative for a discount such as no cheese, zero for a free choice.';
COMMENT ON COLUMN "modifiers"."is_default" IS 'Preselected when the picker opens. Defaults still produce order_item_modifiers rows, so a receipt shows what was actually on the dish.';
COMMENT ON COLUMN "modifiers"."is_available" IS 'Lets the kitchen kill a single option without taking down the group.';
COMMENT ON COLUMN "modifiers"."position" IS 'Sort order within the group.';

CREATE INDEX "idx_modifiers_group_position"
ON "modifiers" ("modifier_group_id", "position");

CREATE TABLE IF NOT EXISTS "menu_item_modifier_groups" (
	-- Item the group is attached to. Half of the composite key; no surrogate id, because the pair is the identity.
	"menu_item_id" BIGINT,
	-- Group being attached.
	"modifier_group_id" BIGINT,
	-- Order the groups appear in for this item, which is often not the group default order.
	"position" INTEGER NOT NULL DEFAULT 0,
	-- Per-item lower bound. Null falls back to the group. Lets a shared Choose a sauce group be optional on fries and required on wings.
	"min_choices_override" INTEGER,
	-- Per-item upper bound. Null falls back to the group.
	"max_choices_override" INTEGER,
	PRIMARY KEY("menu_item_id", "modifier_group_id")
);

COMMENT ON TABLE "menu_item_modifier_groups" IS 'The many-to-many that makes modifier groups reusable. The override columns are why a restaurant can define a question once and still tune it per dish.';
COMMENT ON COLUMN "menu_item_modifier_groups"."menu_item_id" IS 'Item the group is attached to. Half of the composite key; no surrogate id, because the pair is the identity.';
COMMENT ON COLUMN "menu_item_modifier_groups"."modifier_group_id" IS 'Group being attached.';
COMMENT ON COLUMN "menu_item_modifier_groups"."position" IS 'Order the groups appear in for this item, which is often not the group default order.';
COMMENT ON COLUMN "menu_item_modifier_groups"."min_choices_override" IS 'Per-item lower bound. Null falls back to the group. Lets a shared Choose a sauce group be optional on fries and required on wings.';
COMMENT ON COLUMN "menu_item_modifier_groups"."max_choices_override" IS 'Per-item upper bound. Null falls back to the group.';

CREATE TABLE IF NOT EXISTS "orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Who ordered.
	"customer_id" BIGINT NOT NULL,
	-- Who cooks it.
	"restaurant_id" BIGINT NOT NULL,
	-- Assigned courier. Null until a dispatch offer is accepted, and it stays null forever on a cancelled or pickup order.
	"courier_id" BIGINT,
	-- Short human reference read aloud at the counter and quoted to support.
	"order_code" VARCHAR(16) NOT NULL UNIQUE,
	-- placed | accepted | preparing | ready | picked_up | delivered | cancelled.
	"status" VARCHAR(24) NOT NULL DEFAULT 'placed',
	-- Frozen copy of the dropoff address, written once at checkout. Never a foreign key: editing a saved address must not change where a past order went.
	"delivery_address" JSON NOT NULL,
	-- Dropoff latitude, resolved at checkout so dispatch never re-geocodes mid-delivery.
	"delivery_latitude" DECIMAL(9,6) NOT NULL,
	-- Dropoff longitude, same.
	"delivery_longitude" DECIMAL(9,6) NOT NULL,
	-- Free text for the courier, e.g. gate code. Shown only while the delivery is active.
	"delivery_instructions" VARCHAR(400),
	-- Sum of line totals, modifiers included, before fees and tax.
	"subtotal_cents" INTEGER NOT NULL,
	-- Tax charged to the customer, in minor units.
	"tax_cents" INTEGER NOT NULL DEFAULT 0,
	-- Tip at checkout. Mutable until a cutoff after delivery, which is why it is a column here and also a fee row once settled.
	"tip_cents" INTEGER NOT NULL DEFAULT 0,
	-- What the card was charged. Must equal subtotal + tax + customer-payable fees + tip.
	"total_cents" INTEGER NOT NULL,
	-- ISO 4217 currency for every amount on this order.
	"currency_code" CHAR(3) NOT NULL,
	-- Delivery estimate shown at checkout. Kept even when missed, because lateness is measured against the promise, not against a later revision.
	"promised_at" TIMESTAMP,
	-- Checkout completion.
	"placed_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Restaurant tablet acknowledgement.
	"accepted_at" TIMESTAMP,
	-- Bag on the shelf. The gap to picked_up_at is courier wait time, which is paid.
	"ready_at" TIMESTAMP,
	-- Courier took the bag.
	"picked_up_at" TIMESTAMP,
	-- Handover or dropoff photo.
	"delivered_at" TIMESTAMP,
	-- Set on cancellation. The row is kept, never deleted, because refunds and courier compensation hang off it.
	"cancelled_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "orders" IS 'The financial and logistical record of one delivery. The timestamp column per lifecycle event, rather than a single updated_at, is what makes every operational metric a subtraction instead of a scan of an event log.';
COMMENT ON COLUMN "orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "orders"."customer_id" IS 'Who ordered.';
COMMENT ON COLUMN "orders"."restaurant_id" IS 'Who cooks it.';
COMMENT ON COLUMN "orders"."courier_id" IS 'Assigned courier. Null until a dispatch offer is accepted, and it stays null forever on a cancelled or pickup order.';
COMMENT ON COLUMN "orders"."order_code" IS 'Short human reference read aloud at the counter and quoted to support.';
COMMENT ON COLUMN "orders"."status" IS 'placed | accepted | preparing | ready | picked_up | delivered | cancelled.';
COMMENT ON COLUMN "orders"."delivery_address" IS 'Frozen copy of the dropoff address, written once at checkout. Never a foreign key: editing a saved address must not change where a past order went.';
COMMENT ON COLUMN "orders"."delivery_latitude" IS 'Dropoff latitude, resolved at checkout so dispatch never re-geocodes mid-delivery.';
COMMENT ON COLUMN "orders"."delivery_longitude" IS 'Dropoff longitude, same.';
COMMENT ON COLUMN "orders"."delivery_instructions" IS 'Free text for the courier, e.g. gate code. Shown only while the delivery is active.';
COMMENT ON COLUMN "orders"."subtotal_cents" IS 'Sum of line totals, modifiers included, before fees and tax.';
COMMENT ON COLUMN "orders"."tax_cents" IS 'Tax charged to the customer, in minor units.';
COMMENT ON COLUMN "orders"."tip_cents" IS 'Tip at checkout. Mutable until a cutoff after delivery, which is why it is a column here and also a fee row once settled.';
COMMENT ON COLUMN "orders"."total_cents" IS 'What the card was charged. Must equal subtotal + tax + customer-payable fees + tip.';
COMMENT ON COLUMN "orders"."currency_code" IS 'ISO 4217 currency for every amount on this order.';
COMMENT ON COLUMN "orders"."promised_at" IS 'Delivery estimate shown at checkout. Kept even when missed, because lateness is measured against the promise, not against a later revision.';
COMMENT ON COLUMN "orders"."placed_at" IS 'Checkout completion.';
COMMENT ON COLUMN "orders"."accepted_at" IS 'Restaurant tablet acknowledgement.';
COMMENT ON COLUMN "orders"."ready_at" IS 'Bag on the shelf. The gap to picked_up_at is courier wait time, which is paid.';
COMMENT ON COLUMN "orders"."picked_up_at" IS 'Courier took the bag.';
COMMENT ON COLUMN "orders"."delivered_at" IS 'Handover or dropoff photo.';
COMMENT ON COLUMN "orders"."cancelled_at" IS 'Set on cancellation. The row is kept, never deleted, because refunds and courier compensation hang off it.';

CREATE INDEX "idx_orders_restaurant_placed"
ON "orders" ("restaurant_id", "placed_at");
CREATE INDEX "idx_orders_courier_status"
ON "orders" ("courier_id", "status");
CREATE INDEX "idx_orders_status"
ON "orders" ("status");

CREATE TABLE IF NOT EXISTS "order_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent order.
	"order_id" BIGINT NOT NULL,
	-- Item ordered. Nullable so a delisted dish can be hard-deleted without shredding order history.
	"menu_item_id" BIGINT,
	-- Dish name exactly as it read on the menu that day.
	"name_snapshot" VARCHAR(200) NOT NULL,
	-- Units of this configured line. Two differently configured burritos are two rows, not quantity 2.
	"quantity" INTEGER NOT NULL DEFAULT 1,
	-- Item base price at order time, before modifiers.
	"unit_base_price_cents" INTEGER NOT NULL,
	-- Base price plus the sum of this line modifier deltas. Stored so the arithmetic on the receipt is auditable rather than recomputed.
	"unit_total_cents" INTEGER NOT NULL,
	-- quantity * unit_total_cents.
	"line_total_cents" INTEGER NOT NULL,
	-- Free text to the kitchen. Deliberately not priced and not parsed.
	"special_instructions" VARCHAR(400),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "order_items" IS 'One configured dish on an order. Everything that affects the price is snapshotted, because a receipt from last year has to render identically after the menu has been rewritten twice.';
COMMENT ON COLUMN "order_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "order_items"."order_id" IS 'Parent order.';
COMMENT ON COLUMN "order_items"."menu_item_id" IS 'Item ordered. Nullable so a delisted dish can be hard-deleted without shredding order history.';
COMMENT ON COLUMN "order_items"."name_snapshot" IS 'Dish name exactly as it read on the menu that day.';
COMMENT ON COLUMN "order_items"."quantity" IS 'Units of this configured line. Two differently configured burritos are two rows, not quantity 2.';
COMMENT ON COLUMN "order_items"."unit_base_price_cents" IS 'Item base price at order time, before modifiers.';
COMMENT ON COLUMN "order_items"."unit_total_cents" IS 'Base price plus the sum of this line modifier deltas. Stored so the arithmetic on the receipt is auditable rather than recomputed.';
COMMENT ON COLUMN "order_items"."line_total_cents" IS 'quantity * unit_total_cents.';
COMMENT ON COLUMN "order_items"."special_instructions" IS 'Free text to the kitchen. Deliberately not priced and not parsed.';

CREATE INDEX "idx_order_items_order"
ON "order_items" ("order_id");

CREATE TABLE IF NOT EXISTS "order_item_modifiers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Line this choice belongs to.
	"order_item_id" BIGINT NOT NULL,
	-- Modifier chosen. Nullable: the option may be deleted later, and the snapshot columns carry the meaning.
	"modifier_id" BIGINT,
	-- Question text as asked, e.g. Choose a protein. Without it a receipt cannot explain why Chicken costs 2.00.
	"group_name_snapshot" VARCHAR(120) NOT NULL,
	-- Option label as chosen.
	"modifier_name_snapshot" VARCHAR(120) NOT NULL,
	-- The delta actually applied. Re-reading it from modifiers would silently reprice historic orders.
	"price_delta_cents" INTEGER NOT NULL DEFAULT 0,
	-- How many times the option was taken, for groups that allow duplicates.
	"quantity" INTEGER NOT NULL DEFAULT 1,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "order_item_modifiers" IS 'The snapshotted customisation of a line. This is the table the kitchen ticket is printed from and the one a dispute is settled with, which is why it stores text rather than trusting the join.';
COMMENT ON COLUMN "order_item_modifiers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "order_item_modifiers"."order_item_id" IS 'Line this choice belongs to.';
COMMENT ON COLUMN "order_item_modifiers"."modifier_id" IS 'Modifier chosen. Nullable: the option may be deleted later, and the snapshot columns carry the meaning.';
COMMENT ON COLUMN "order_item_modifiers"."group_name_snapshot" IS 'Question text as asked, e.g. Choose a protein. Without it a receipt cannot explain why Chicken costs 2.00.';
COMMENT ON COLUMN "order_item_modifiers"."modifier_name_snapshot" IS 'Option label as chosen.';
COMMENT ON COLUMN "order_item_modifiers"."price_delta_cents" IS 'The delta actually applied. Re-reading it from modifiers would silently reprice historic orders.';
COMMENT ON COLUMN "order_item_modifiers"."quantity" IS 'How many times the option was taken, for groups that allow duplicates.';

CREATE INDEX "idx_order_item_modifiers_item"
ON "order_item_modifiers" ("order_item_id");

CREATE TABLE IF NOT EXISTS "couriers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Name shown to the customer while the delivery is live.
	"full_name" VARCHAR(160) NOT NULL,
	-- E.164 number, also the login identity.
	"phone" VARCHAR(32) NOT NULL UNIQUE,
	-- car | bike | scooter | walk. Changes routing speed and which orders can be offered.
	"vehicle_type" VARCHAR(20) NOT NULL DEFAULT 'car',
	-- offline | available | on_delivery | on_break. Only available couriers enter the dispatch pool.
	"status" VARCHAR(20) NOT NULL DEFAULT 'offline',
	-- Last known latitude, overwritten on every ping. Null while offline.
	"current_latitude" DECIMAL(9,6),
	-- Last known longitude, overwritten on every ping.
	"current_longitude" DECIMAL(9,6),
	-- When the cached position was last written. A stale value is treated as offline regardless of status.
	"location_updated_at" TIMESTAMP,
	-- Rolling average of delivery ratings. Null until enough deliveries to be meaningful.
	"rating_avg" DECIMAL(3,2),
	-- Approval time.
	"onboarded_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "couriers" IS 'A delivery worker plus a cached last position. The cache is denormalised on purpose: dispatch runs a nearest-courier query every few seconds and cannot afford to sort a ping history to find it.';
COMMENT ON COLUMN "couriers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "couriers"."full_name" IS 'Name shown to the customer while the delivery is live.';
COMMENT ON COLUMN "couriers"."phone" IS 'E.164 number, also the login identity.';
COMMENT ON COLUMN "couriers"."vehicle_type" IS 'car | bike | scooter | walk. Changes routing speed and which orders can be offered.';
COMMENT ON COLUMN "couriers"."status" IS 'offline | available | on_delivery | on_break. Only available couriers enter the dispatch pool.';
COMMENT ON COLUMN "couriers"."current_latitude" IS 'Last known latitude, overwritten on every ping. Null while offline.';
COMMENT ON COLUMN "couriers"."current_longitude" IS 'Last known longitude, overwritten on every ping.';
COMMENT ON COLUMN "couriers"."location_updated_at" IS 'When the cached position was last written. A stale value is treated as offline regardless of status.';
COMMENT ON COLUMN "couriers"."rating_avg" IS 'Rolling average of delivery ratings. Null until enough deliveries to be meaningful.';
COMMENT ON COLUMN "couriers"."onboarded_at" IS 'Approval time.';

CREATE INDEX "idx_couriers_status_location"
ON "couriers" ("status", "location_updated_at");

CREATE TABLE IF NOT EXISTS "dispatch_offers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Order being offered.
	"order_id" BIGINT NOT NULL,
	-- Courier the offer went to.
	"courier_id" BIGINT NOT NULL,
	-- Attempt number for this order, starting at 1. An order that took six offers to place tells you the market was short, and that is only visible if every attempt is a row.
	"sequence" INTEGER NOT NULL,
	-- When the push notification was sent.
	"offered_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Auto-decline deadline, usually under a minute. Dispatch must not wait on a phone in a pocket.
	"expires_at" TIMESTAMP NOT NULL,
	-- When the courier tapped. Null if it timed out.
	"responded_at" TIMESTAMP,
	-- pending | accepted | declined | expired.
	"response" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Courier-to-restaurant distance when the offer was made, kept for dispatch model evaluation.
	"distance_meters" INTEGER NOT NULL,
	-- What the courier was shown. Must be honoured even if the actual route turns out shorter, so it is stored, not recomputed.
	"projected_payout_cents" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "dispatch_offers" IS 'One offer to one courier. At most one row per order may be accepted, enforced in the transaction that also sets orders.courier_id, which is what stops two couriers racing to the same restaurant.';
COMMENT ON COLUMN "dispatch_offers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "dispatch_offers"."order_id" IS 'Order being offered.';
COMMENT ON COLUMN "dispatch_offers"."courier_id" IS 'Courier the offer went to.';
COMMENT ON COLUMN "dispatch_offers"."sequence" IS 'Attempt number for this order, starting at 1. An order that took six offers to place tells you the market was short, and that is only visible if every attempt is a row.';
COMMENT ON COLUMN "dispatch_offers"."offered_at" IS 'When the push notification was sent.';
COMMENT ON COLUMN "dispatch_offers"."expires_at" IS 'Auto-decline deadline, usually under a minute. Dispatch must not wait on a phone in a pocket.';
COMMENT ON COLUMN "dispatch_offers"."responded_at" IS 'When the courier tapped. Null if it timed out.';
COMMENT ON COLUMN "dispatch_offers"."response" IS 'pending | accepted | declined | expired.';
COMMENT ON COLUMN "dispatch_offers"."distance_meters" IS 'Courier-to-restaurant distance when the offer was made, kept for dispatch model evaluation.';
COMMENT ON COLUMN "dispatch_offers"."projected_payout_cents" IS 'What the courier was shown. Must be honoured even if the actual route turns out shorter, so it is stored, not recomputed.';

CREATE UNIQUE INDEX "uq_dispatch_offers_order_sequence"
ON "dispatch_offers" ("order_id", "sequence");
CREATE INDEX "idx_dispatch_offers_courier_response"
ON "dispatch_offers" ("courier_id", "response");

CREATE TABLE IF NOT EXISTS "courier_pings" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Courier the device belongs to.
	"courier_id" BIGINT NOT NULL,
	-- Active order at the time of the ping. Null while idle, which keeps idle tracking separable from delivery tracking for privacy retention rules.
	"order_id" BIGINT,
	-- Device clock time of the fix, not server receipt time. Pings arrive out of order over flaky mobile data and must be sorted by this.
	"recorded_at" TIMESTAMP NOT NULL,
	-- Fix latitude.
	"latitude" DECIMAL(9,6) NOT NULL,
	-- Fix longitude.
	"longitude" DECIMAL(9,6) NOT NULL,
	-- Reported horizontal accuracy. Fixes worse than about 100 m are dropped before they reach the customer map.
	"accuracy_meters" INTEGER,
	-- Reported ground speed, used to smooth the map and to detect a stopped courier.
	"speed_mps" DECIMAL(6,2),
	-- Course over ground, 0-359. Rotates the map arrow.
	"heading_degrees" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "courier_pings" IS 'The raw location stream. It is append-only, enormous, and the only table here with a retention policy: pings are aggregated into a route and dropped after a few weeks.';
COMMENT ON COLUMN "courier_pings"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "courier_pings"."courier_id" IS 'Courier the device belongs to.';
COMMENT ON COLUMN "courier_pings"."order_id" IS 'Active order at the time of the ping. Null while idle, which keeps idle tracking separable from delivery tracking for privacy retention rules.';
COMMENT ON COLUMN "courier_pings"."recorded_at" IS 'Device clock time of the fix, not server receipt time. Pings arrive out of order over flaky mobile data and must be sorted by this.';
COMMENT ON COLUMN "courier_pings"."latitude" IS 'Fix latitude.';
COMMENT ON COLUMN "courier_pings"."longitude" IS 'Fix longitude.';
COMMENT ON COLUMN "courier_pings"."accuracy_meters" IS 'Reported horizontal accuracy. Fixes worse than about 100 m are dropped before they reach the customer map.';
COMMENT ON COLUMN "courier_pings"."speed_mps" IS 'Reported ground speed, used to smooth the map and to detect a stopped courier.';
COMMENT ON COLUMN "courier_pings"."heading_degrees" IS 'Course over ground, 0-359. Rotates the map arrow.';

CREATE INDEX "idx_courier_pings_order_time"
ON "courier_pings" ("order_id", "recorded_at");
CREATE INDEX "idx_courier_pings_courier_time"
ON "courier_pings" ("courier_id", "recorded_at");

CREATE TABLE IF NOT EXISTS "order_fees" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Order being settled.
	"order_id" BIGINT NOT NULL,
	-- delivery_fee | service_fee | small_order_fee | restaurant_commission | courier_base_pay | courier_mileage | courier_wait_pay | tip | promo_discount.
	"fee_type" VARCHAR(32) NOT NULL,
	-- customer | restaurant | platform. Who the money leaves.
	"payer" VARCHAR(16) NOT NULL,
	-- courier | restaurant | platform. Who the money reaches.
	"payee" VARCHAR(16) NOT NULL,
	-- Amount moved, in minor units. Always positive; direction is carried by payer and payee, not by sign.
	"amount_cents" INTEGER NOT NULL,
	-- ISO 4217 currency of amount_cents.
	"currency_code" CHAR(3) NOT NULL,
	-- How the number was reached, e.g. 15 percent of 2400. Kept because a courier or a restaurant will eventually ask.
	"basis_note" VARCHAR(200),
	-- When the fee was computed. Late tip adjustments append a row here rather than editing one.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "order_fees" IS 'One row per movement of money on an order, expressed as payer to payee. Three payouts and one customer charge come out of the same table, and they balance by construction.';
COMMENT ON COLUMN "order_fees"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "order_fees"."order_id" IS 'Order being settled.';
COMMENT ON COLUMN "order_fees"."fee_type" IS 'delivery_fee | service_fee | small_order_fee | restaurant_commission | courier_base_pay | courier_mileage | courier_wait_pay | tip | promo_discount.';
COMMENT ON COLUMN "order_fees"."payer" IS 'customer | restaurant | platform. Who the money leaves.';
COMMENT ON COLUMN "order_fees"."payee" IS 'courier | restaurant | platform. Who the money reaches.';
COMMENT ON COLUMN "order_fees"."amount_cents" IS 'Amount moved, in minor units. Always positive; direction is carried by payer and payee, not by sign.';
COMMENT ON COLUMN "order_fees"."currency_code" IS 'ISO 4217 currency of amount_cents.';
COMMENT ON COLUMN "order_fees"."basis_note" IS 'How the number was reached, e.g. 15 percent of 2400. Kept because a courier or a restaurant will eventually ask.';
COMMENT ON COLUMN "order_fees"."created_at" IS 'When the fee was computed. Late tip adjustments append a row here rather than editing one.';

CREATE INDEX "idx_order_fees_order_type"
ON "order_fees" ("order_id", "fee_type");
CREATE INDEX "idx_order_fees_payee_created"
ON "order_fees" ("payee", "created_at");

